const QB=QB_RAW.split('\n').map(l=>l.split('|'));
const QCATS=[...new Set(QB.map(r=>r[0]))];
function drawQuiz(n){const by={};QB.forEach(r=>(by[r[0]]=by[r[0]]||[]).push(r));const out=shuffle(by['언론']).slice(0,2);const cats=shuffle(QCATS.filter(c=>c!=='언론'));let i=0;while(out.length<n){const c=cats[i%cats.length];const cand=shuffle(by[c]).find(r=>!out.includes(r));if(cand)out.push(cand);i++;if(i>200)break;}return shuffle(out).map(r=>({c:r[0],q:r[1],a:r[2],o:shuffle(r.slice(2))}));}
