// 치환어 뒤 조사를 받침에 맞춘다: {S}는 → 기관은/기관는
const JP={'은':['은','는'],'는':['은','는'],'이':['이','가'],'가':['이','가'],'을':['을','를'],'를':['을','를'],'과':['과','와'],'와':['과','와']};
function subJ(s,tok,w){const re=tok.replace(/[{}]/g,'\\$&');return String(s).replace(new RegExp(re+'(은|는|이|가|을|를|과|와)(?![가-힣])','g'),(m,p)=>jo2(w,JP[p][0],JP[p][1])).split(tok).join(w);}
function cleanFor(d,subj){const k=CLEAN_C[d]?d:'all';const pool=CLEAN_C.all.concat(CLEAN_C[k]||[],CLEAN_C[k]||[]);return pool.map(x=>subJ(x,'{S}',subj||'해당 기관'));}

(function(){const who=['{S} 측','관계 기관','담당 부서','감독 기관','해당 지자체'],when=['다음 주','이달 말','다음 달 초','올해 안','연말까지'],what=[['결과를 발표할 계획이다','결과 발표'],['재발 방지책을 내놓기로 했다','대책'],['외부 전문가에게 조사를 맡길 방침이다','외부 조사'],['관련자 징계 여부를 결정할 예정이다','징계 결정'],['전수 조사를 마칠 예정이다','전수 조사'],['개선안을 공개하기로 했다','개선안']];
 who.forEach(w=>when.forEach((t,i)=>{const x=what[(i+who.indexOf(w))%what.length];CLEAN_C.all.push(`${jo2(w,'은','는')} ${t} ${x[0]}.`.replace('측은','측은').replace(/([가-힣])은 /,(m,c)=>((c.charCodeAt(0)-44032)%28?c+'은 ':c+'는 '))); }));
 const src=['국가통계포털(KOSIS)','감사원 감사 보고서','국회 입법조사처 자료','국민권익위원회 자료','법원 판결문','금융감독원 전자공시','건강보험심사평가원 자료','행정안전부 자료','고용노동부 통계','교육부 학교알리미'];
 src.forEach(x=>CLEAN_C.all.push(`이 수치는 ${jo2(x,'을','를')} 본지가 분석한 결과다.`));
 ['3년','5년','10년'].forEach(y=>['비슷한 민원','같은 유형의 사고','관련 소송'].forEach(z=>CLEAN_C.all.push(`최근 ${y}간 ${jo2(z,'은','는')} 꾸준히 늘었다고 관계 기관 자료는 밝히고 있다.`)));
})();
const CLEAN=CLEAN_C.all.concat(CLEAN_C.soc);
function flawFor(subj){return shuffle(FLAWS).map(f=>({t:subJ(f.t,'{S}',subj||'A씨'),e:f.e}));}

