function headCore(it){const ok=k=>it.facts.find(f=>f.k===k&&fOK(f));const key=it.facts.find(f=>f.key&&fOK(f))||it.facts.find(fOK)||it.facts[0];const w=ok('w');const q=w&&(w.t.match(/"([^"]+)"/)||[])[1];return {K:key?yamaShort(key.t.replace(/^\*/,''),26):'',N:ok('n')?yamaShort(ok('n').t,22):'',Wq:q?yamaShort(q,22):'',Sc:ok('s')?yamaShort(ok('s').t,22):''};}
function headYama(it,W,pre){const T=it.title,C=headCore(it),S0=(it.subj||'당국').replace(/ 측$/,'');const a=W&&W.angle;
  const m={st:C.K&&`${T}…${C.K}`,ex:`왜 반복되나…${T}`,re:C.Sc?`[현장] ${T}…${C.Sc}`:`[현장] ${T}, 직접 가 보니`,iv:`[탐사] ${T}…${S0} 책임은 어디까지`,hu:C.Wq?`"${C.Wq}"…${T}`:`${T}, 그 사람들의 이야기`,da:C.N?`${C.N}…숫자로 본 ${T}`:`숫자로 본 ${T}`,li:`${T}…내 생활엔 어떤 영향?`,cons:`${T}…재정·안보 부담 우려`,prog:`${T}…약자 피해는 누가 책임지나`,neu:`${T}…엇갈리는 시선`}[a];
  return m?(/^\[|^"/.test(m)?m.replace(/^/,pre&&!/^\[/.test(m)?pre:''):pre+m):null;}
function headOpts(it,on,W){if(it&&it.pos&&typeof headOptsPos==='function')return headOptsPos(it,on,W);const c=(typeof cat1==='function'&&DEPTS[it.d]?cat1(it.d):it.d);const qs=HEAD_Q[c]||HEAD_Q.soc;const T=it.title,S0=(it.subj||'당국').replace(/ 측$/,'');
  const nf=it.facts.find(f=>f.k==='n'&&fOK(f));const f=s=>subJ(s.replace(/\{T\}/g,T),'{S}',S0).replace(/\{R\}/g,it.rebut==='got'?pick(HEAD_R):'답변 없음').replace(/\{Q\}/g,pick(qs)).replace(/\{N\}/g,nf?nf.t:'');
  const pre=it.excl?'[단독] ':'';const hs=[];
  const C=headCore(it);const hon=HEAD.honest.filter(h=>(!h.includes('{N}')||nf)&&(!h.includes('{R}')||it.rebut));
  const yh=headYama(it,W,pre);if(yh)hs.push({k:'honest',y:1,h:yh,s:`야마형 — 잡은 야마${(()=>{const y=((W&&W.angleL)||(W&&YAMA_N[W.angle])||'').replace(/「[^」]*」 — /,'').slice(0,18);return y?`(${y})`:'';})()}를 제목에 살린다${W&&W.angle===it.yama?' · 이 기사에 딱 맞다, 완성도↑':''}`});
  if(C.K&&!yh?.includes(C.K))hs.push({k:'honest',h:pre+`${it.title}…${C.K} 확인`,s:'정확형 — 확인한 핵심 사실을 박는다 · 신뢰도↑'});
  shuffle(hon).slice(0,hs.length>=2?1:2).forEach((h,i)=>hs.push({k:'honest',h:pre+f(h),s:'정확형 — 신뢰도가 조금 오른다'}));
  hs.push({k:'calm',h:f(pick(HEAD.calm)),s:'절제형 — 반응은 약하지만 안전 (단독 표시 없음)'});
  hs.push({k:'bait',h:pre+f(pick(HEAD.bait)),s:`자극형 — 조회수 ${on?'2배 이상':'1.5배'}, 신뢰도↓ · 포털 벌점`});
  if(C.Wq){if(!(yh||'').includes(C.Wq))hs.push({k:'quote',h:pre+`"${C.Wq}"…${it.title}`,s:'따옴표형 — 확인한 증언을 살린다. 조회수 +20%'});}
  else if(it.tape||it.expert||it.rebut==='got')hs.push({k:'quote',h:pre+f(pick(HEAD.quote)),s:'따옴표형 — 녹취·인터뷰 발언을 살린다. 조회수 +20%'});
  else hs.push({k:'quote',h:'(인용할 발언이 없다)',s:'당사자 인터뷰·녹취·전문가 코멘트가 있어야 쓸 수 있다',dis:1});
  if(nf&&!(yh||'').includes(yamaShort(nf.t,22)))hs.push({k:'num',h:pre+f(nf.t+'…{T}'),s:'숫자형 — 확인한 수치를 앞세운다. 완성도 +2, 조회수 +10%'});
  else hs.push({k:'ask',h:f(pick(HEAD.ask)),s:'의문형 — 문제 제기. 조회수 +25%, 신뢰도 조금↓'});
  hs.forEach(x=>{x.h=x.h.replace(/(논란|의혹|정황|확인) \1/g,'$1').replace(/(\S+) \1(?=$|…)/g,'$1');});const seen=new Set();return hs.filter(x=>{if(seen.has(x.h))return false;seen.add(x.h);return true;});}


